<?php
namespace Tests\Feature; use App\Models\Currency; use App\Models\Property; use App\Models\Role; use App\Models\User; use Database\Seeders\CoreSeeder; use Database\Seeders\RolePermissionSeeder; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class PropertyWorkflowTest extends TestCase {use RefreshDatabase; public function test_agent_can_create_draft():void{$this->seed(CoreSeeder::class);$this->seed(RolePermissionSeeder::class);$u=User::factory()->create();$u->roles()->attach(Role::where('slug','agent')->value('id'));$c=Currency::first();$this->actingAs($u)->post('/dashboard/properties',['purpose'=>'sale','price'=>100000,'currency_id'=>$c->id,'reference_code'=>'TEST-001','translations'=>['en'=>['name'=>'Test Property','slug'=>'test-property']]])->assertRedirect();$this->assertDatabaseHas('properties',['reference_code'=>'TEST-001','status'=>'draft']);}}
